RouteTable[2,3] <- 2
RouteTable[3,1] <- -1
RouteTable[4,1] <- 260
RouteTable[4,2] <- 399
RouteTable[4,3] <- 2
RouteTable[5,1] <- 400
RouteTable[5,2] <- 599
RouteTable[5,3] <- 3
