export function taskById(id) {
  return TASKS.find((task) => task.id === id) || null;
}

// Assemble the program that the judge runs: setup + the student's answer + checks.
export function buildProgram(task, entry, studentCode) {
  if (task.kind === "program") return studentCode;
  const setup = entry.setup !== undefined ? entry.setup : (task.setup || "");
  const after = entry.after !== undefined ? entry.after : (task.after || "");
  return `${setup}\n${studentCode}\n${after}\n`;
}

export function resultOf(output) {
  const index = output.indexOf(RESULT_MARKER);
  if (index === -1) return output.trimEnd();
  return output.slice(index + RESULT_MARKER.length).replace(/^\s*\n/, "").trimEnd();
}

// Setup builders for the tasks above whose array data is generated rather than typed out.
// Function declarations are hoisted, so the tasks can use them during module evaluation.

function secretSetup(rows) {
  let code = `DECLARE Secret : ARRAY[1:500, 1:2] OF STRING
DECLARE I : INTEGER
FOR I <- 1 TO 500
    Secret[I, 1] <- ""
    Secret[I, 2] <- ""
NEXT I
FUNCTION Decrypt(Encrypted : STRING) RETURNS STRING
    RETURN Encrypted
ENDFUNCTION
`;
  rows.forEach(([domain, password], index) => {
    const row = index + 1;
    code += `Secret[${row}, 1] <- "${domain}"\nSecret[${row}, 2] <- "${password}"\n`;
  });
  return code;
}

function specialSetup(fillings, breads) {
  let code = `DECLARE Filling : ARRAY[1:35] OF STRING
DECLARE Bread : ARRAY[1:10] OF STRING
DECLARE I : INTEGER
FOR I <- 1 TO 35
    Filling[I] <- ""
NEXT I
FOR I <- 1 TO 10
    Bread[I] <- ""
NEXT I
`;
  fillings.forEach(([index, name]) => {
    code += `Filling[${index}] <- "${name}"\n`;
  });
  breads.forEach(([index, name]) => {
    code += `Bread[${index}] <- "${name}"\n`;
  });
  return code;
}

function errorSetup(codes, texts) {
  let code = `DECLARE ErrCode : ARRAY[1:500] OF INTEGER
DECLARE ErrText : ARRAY[1:500] OF STRING
DECLARE I : INTEGER
FOR I <- 1 TO 500
    ErrCode[I] <- 999
    ErrText[I] <- ""
NEXT I
`;
  codes.forEach((codeValue, index) => {
    const row = index + 1;
    code += `ErrCode[${row}] <- ${codeValue}\nErrText[${row}] <- "${texts[index]}"\n`;
  });
  return code;
}

function logArraySetup(entries) {
  let code = `DECLARE LogArray : ARRAY[1:2000] OF STRING
DECLARE FillIndex : INTEGER
FOR FillIndex <- 1 TO 2000
    LogArray[FillIndex] <- ""
NEXT FillIndex
`;
  for (const [index, value] of entries) {
    code += `LogArray[${index}] <- "${value}"\n`;
  }
  return code;
}

function inboxSetup(messages) {
  let code = `DECLARE Inbox : ARRAY[1:10] OF STRING
DECLARE InboxPos : INTEGER
DECLARE FillIndex : INTEGER
FOR FillIndex <- 1 TO 10
    Inbox[FillIndex] <- ""
NEXT FillIndex
`;
  messages.forEach((message, index) => {
    code += `Inbox[${index + 1}] <- "${message}"\n`;
  });
  code += `InboxPos <- 1
FUNCTION GetData() RETURNS STRING
    DECLARE Result : STRING
    Result <- Inbox[InboxPos]
    InboxPos <- InboxPos + 1
    RETURN Result
ENDFUNCTION
`;
  return code;
}

function gradeSetup(rows) {
  let code = `DECLARE GradeBoundary : ARRAY[1:5] OF INTEGER
DECLARE Result : ARRAY[1:20, 1:2] OF INTEGER
DECLARE FillRow : INTEGER
GradeBoundary[1] <- 65
GradeBoundary[2] <- 57
GradeBoundary[3] <- 43
GradeBoundary[4] <- 35
GradeBoundary[5] <- 27
FOR FillRow <- 1 TO 20
    Result[FillRow, 1] <- 0
    Result[FillRow, 2] <- 0
NEXT FillRow
`;
  rows.forEach(([mark, id], index) => {
    const row = index + 1;
    code += `Result[${row}, 1] <- ${mark}\nResult[${row}, 2] <- ${id}\n`;
  });
  code += `FUNCTION CheckMark(Mark : INTEGER) RETURNS BOOLEAN
    DECLARE Index : INTEGER
    FOR Index <- 1 TO 5
        IF Mark >= GradeBoundary[Index] - 2 AND Mark <= GradeBoundary[Index] + 2 THEN
            RETURN TRUE
        ENDIF
    NEXT Index
    RETURN FALSE
ENDFUNCTION
`;
  return code;
}

